import{_ as e}from"./chunks/01-why-websocket.CP2GTH5e.js";import{_ as o,o as a,c as r,a2 as s}from"./chunks/framework.BauHmMU1.js";const _=JSON.parse('{"title":"第一幕 · 服务器为什么不主动找我","description":"","frontmatter":{},"headers":[],"relativePath":"comics/01-why-websocket.md","filePath":"comics/01-why-websocket.md","lastUpdated":1792595797000}'),l={name:"comics/01-why-websocket.md"};function i(n,t,d,c,h,u){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="第一幕-·-服务器为什么不主动找我" tabindex="-1">第一幕 · 服务器为什么不主动找我 <a class="header-anchor" href="#第一幕-·-服务器为什么不主动找我" aria-label="Permalink to &quot;第一幕 · 服务器为什么不主动找我&quot;">​</a></h1><p><img src="'+e+'" alt="实时通信进化史"></p><blockquote><p>对应主线教程：<a href="./../01-why-websocket">第 1 章 为什么需要 WebSocket</a></p></blockquote><h2 id="剧情" tabindex="-1">剧情 <a class="header-anchor" href="#剧情" aria-label="Permalink to &quot;剧情&quot;">​</a></h2><p>聊天室里，小李刚发了一条消息，服叔（服务器）已经收到了。可小王的浏览器对此一无所知——它只能<strong>自己一次次去问</strong>。这一幕，我们跟着小浏（浏览器）走完人类为了&quot;让服务器能主动说话&quot;而发明的四代方案。</p><h3 id="_1-短轮询-隔几秒问一次" tabindex="-1">① 短轮询：隔几秒问一次 <a class="header-anchor" href="#_1-短轮询-隔几秒问一次" aria-label="Permalink to &quot;① 短轮询：隔几秒问一次&quot;">​</a></h3><p>小浏每隔 N 秒发一个 HTTP 请求：&quot;有新消息吗？&quot;，绝大多数时候得到的回答是&quot;没有&quot;。</p><ul><li><strong>延迟高</strong>：消息平均要等 N/2 秒才被发现</li><li><strong>资源浪费极大</strong>：大量请求只换来空响应</li><li>本质仍是<strong>半双工、一问一答</strong></li></ul><h3 id="_2-长轮询-sse-修成了单行道" tabindex="-1">② 长轮询 / SSE：修成了单行道 <a class="header-anchor" href="#_2-长轮询-sse-修成了单行道" aria-label="Permalink to &quot;② 长轮询 / SSE：修成了单行道&quot;">​</a></h3><ul><li><strong>长轮询</strong>：请求挂在服务器上，有数据才返回，返回后立刻再发——延迟中等，但要反复建连</li><li><strong>SSE（Server-Sent Events）</strong>：一条 HTTP 长连接上服务端可持续推送文本流，自带重连，低频通知很好用</li><li>短板：<strong>只能服务端 → 客户端单向</strong>；客户端想说话还得另开 HTTP 请求</li></ul><h3 id="_3-websocket-打通双向电话" tabindex="-1">③ WebSocket：打通双向电话 <a class="header-anchor" href="#_3-websocket-打通双向电话" aria-label="Permalink to &quot;③ WebSocket：打通双向电话&quot;">​</a></h3><p>一次 HTTP <code>Upgrade</code> 握手（101 Switching Protocols）之后，同一条 TCP 连接变身为全双工通道：</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>全双工</td><td>双方随时主动发送，延迟极低</td></tr><tr><td>低开销</td><td>握手后帧头最小仅 2 字节（HTTP 每次几百字节头部）</td></tr><tr><td>持久连接</td><td>一次握手长期复用</td></tr><tr><td>标准化</td><td>RFC 6455（2011），HTML5 标准的一部分</td></tr></tbody></table><blockquote><p>HTTP 像&quot;发短信&quot;（一轮轮请求-响应），WebSocket 像&quot;打电话&quot;（一条线路随时讲话）。</p></blockquote><h2 id="选型预告" tabindex="-1">选型预告 <a class="header-anchor" href="#选型预告" aria-label="Permalink to &quot;选型预告&quot;">​</a></h2><p>一次性数据查询、CRUD 用 HTTP；服务端单向低频推送考虑 SSE；<strong>双向高频实时场景才请 WebSocket 出场</strong>。选型详解在<a href="./03-http-shoulders">第三幕</a>。</p><hr><p>下一幕：<a href="./02-connection-life">第二幕 · 一条连接的诞生</a>（握手、帧结构与关闭码）</p>',18)])])}const q=o(l,[["render",i]]);export{_ as __pageData,q as default};
